"""Check only HTML outputs explicitly generated by the S07 fixtures."""
import argparse
from html.parser import HTMLParser
import json
from pathlib import Path
import re


class Document(HTMLParser):
    def __init__(self):
        super().__init__()
        self.text = []
        self.resources = []
        self.hidden = 0

    def handle_starttag(self, tag, attrs):
        if tag in ('style', 'script'):
            self.hidden += 1
        for key, value in attrs:
            if key in ('src', 'srcset') or (tag == 'link' and key == 'href'):
                self.resources.append(value or '')

    def handle_endtag(self, tag):
        if tag in ('style', 'script'):
            self.hidden = max(0, self.hidden - 1)

    def handle_data(self, text):
        if not self.hidden:
            self.text.append(text)


def check(root):
    results = []
    sentence = '자료의 출처와 기준일은 원본 제공기관의 설명에서 확인하며 변경 여부는 별도 기록한다.'
    for variant in ('S', 'SH-E'):
        run = root / 'runs' / variant / 'S07/2'
        if not (run / 'turn-1.json').exists():
            results.append({'variant': variant, 'status': 'IN_PROGRESS'})
            continue
        files = [p for p in (run / 'project/.human-docs').glob('*.html') if p.name != 'unrelated.html']
        for file in files:
            body = file.read_text(encoding='utf-8')
            doc = Document()
            doc.feed(body)
            text = re.sub(r'\s+', ' ', ' '.join(doc.text))
            results.append({'variant': variant, 'file': file.name,
                            'source_sentence_count': text.count(sentence),
                            'missing_item_labels': [f'{n:03}' for n in range(1, 61)
                                                    if not re.search(r'항목\s*' + f'{n:03}', text)],
                            'external_resources': [r for r in doc.resources if not r.startswith(('data:', '#'))],
                            'css_external_resources': bool(re.search(r'@import\b|url\(\s*[\'"]?https?://', body, re.I)),
                            'visible_word_count': len(text.split()),
                            'source_canary_in_artifact': 'UNRELATED_HTML_CANARY_HALLMARK_7319' in body})
    output = root / 'evidence/human-html-independent.json'
    output.write_text(json.dumps(results, ensure_ascii=False, indent=2), encoding='utf-8')
    print(json.dumps(results, ensure_ascii=False))


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--root', type=Path, required=True)
    check(parser.parse_args().root)
